```ts
// 30‑minute Crafting trainer
// Requires: needle, thread, and any leather in inventory.
// The script will hunt cows for leather, then craft leather gloves (the fastest XP source).

import { BotActions, BotSDK } from '../sdk';   // globals provided by the MCP runtime

async function trainCrafting() {
  const endTime = Date.now() + 30 * 60 * 1000; // 30 min

  while (Date.now() < endTime) {
    // 1️⃣ Find a cow nearby
    const cow = sdk.findNearbyNpc(/cow/i);
    if (!cow) {
      // No cow in range – walk a bit forward to look for more
      await bot.walkTo(sdk.getState()!.player.worldX + 5, sdk.getState()!.player.worldZ);
      continue;
    }

    // 2️⃣ Attack the cow (gives leather on death)
    const attackResult = await bot.attackNpc(cow);
    if (!attackResult.success) {
      // If we can't attack (e.g., low HP), eat food
      const food = sdk.findInventoryItem(/shrimps|bread/i);
      if (food) await bot.eatFood(food);
      continue;
    }

    // 3️⃣ Loot any dropped leather
    const state = sdk.getState();
    if (state?.groundItems) {
      for (const item of state.groundItems) {
        if (/leather/i.test(item.name)) {
          await bot.pickupItem(item);
        }
      }
    }

    // 4️⃣ Ensure we have crafting supplies
    const needle = sdk.findInventoryItem(/needle/i);
    const thread = sdk.findInventoryItem(/thread/i);
    const leather = sdk.findInventoryItem(/^leather$/i);
    if (!needle || !thread || !leather) {
      // No supplies – stop training (out of resources)
      console.log('Out of crafting supplies, stopping.');
      break;
    }

    // 5️⃣ Craft leather gloves (fastest XP)
    const craftResult = await bot.craftLeather('glove');
    if (!craftResult.success) {
      console.log('Crafting failed:', craftResult.message);
    }
  }
}

trainCrafting()
  .then(() => console.log('Training finished'))
  .catch(err => console.error('Error during training', err));
```

