import { BotActions, BotSDK } from "./sdk";   // globals are injected when run via rs‑agent

// Helper: wait for a condition or timeout
async function waitFor<T>(fn: () => T | null, timeoutMs = 5000, poll = 200): Promise<T> {
  const end = Date.now() + timeoutMs;
  while (Date.now() < end) {
    const v = fn();
    if (v) return v;
    await new Promise(r => setTimeout(r, poll));
  }
  throw new Error("waitFor timed out");
}

