// ------------------------------------------------------------------
(async () => {
  const END_TIME = Date.now() + 30 * 60 * 1000;   // 30 minutes

  // Move to a known chicken area (Lumbridge south‑west)
  await bot.walkTo(3215, 3220);

  while (Date.now() < END_TIME) {
    // ----------------------------------------------------------------
    // 1️⃣ Find a chicken and kill it
    // ----------------------------------------------------------------
    const chicken = await waitFor(() => sdk.findNearbyNpc(/chicken/i), 8000).catch(() => null);
    if (chicken) {
      // attack until the NPC dies – the SDK handles combat loops internally
      await bot.attackNpc(chicken);
    } else {
      // nothing nearby – walk a little to refresh the spawn pool
      await bot.walkTo(3215 + Math.floor(Math.random() * 5), 3220 + Math.floor(Math.random() * 5));
      continue;
    }

    // ----------------------------------------------------------------
    // 2️⃣ Bury any bones we just obtained
    // ----------------------------------------------------------------
    // Bones can appear as “Bones”, “Big bones”, “Dragon bones”, etc.
    const bonePatterns = [/bones/i, /big bone/i, /dragon bone/i];
    for (const pat of bonePatterns) {
      const bone = sdk.findInventoryItem(pat);
      if (bone) {
        // `useItem` triggers the default action (bury for bones)
        await bot.useItem(bone);
        // Small pause to let the server process the XP gain
        await new Promise(r => setTimeout(r, 300));
      }
    }
  }

  // ---------------------------------------------------------------
  // End of training – report final state
  // ---------------------------------------------------------------
  const finalState = sdk.getState();
  console.log("Training finished. Prayer XP:", finalState.skills.find(s => s.name === "Prayer")?.xp);
})();
```

**How it works**

1. **Walk to a chicken‑spawning spot** (`3215, 3220`).  
2. **Locate a chicken** (`sdk.findNearbyNpc(/chicken/i)`) and **attack it** (`bot.attackNpc`).  
3. After the kill, **search the inventory for any kind of bones** and **use each bone** (`bot.useItem`), which automatically triggers the “bury” action and awards Prayer XP.  
4. If no chicken is nearby, the script nudges the bot a few tiles to refresh the spawn pool.  
5. The loop repeats until the 30‑minute timer expires, then prints the final Prayer XP.

