// /tmp/hp_train.ts
import { BotActions, BotSDK } from '../sdk';

// Train hitpoints for the given duration (ms)
async function train(bot: BotActions, sdk: BotSDK, durationMs: number) {
  const end = Date.now() + durationMs;
  while (Date.now() < end) {
    // Find the nearest rat
    const rat = sdk.findNearbyNpc(/rat/i);
    if (rat) {
      await bot.attackNpc(rat);          // attack the rat
    } else {
      await new Promise(r => setTimeout(r, 500)); // wait a bit if none found
    }

    // Heal when HP gets low
    const hp = sdk.getSkill('Hitpoints')?.level ?? 0;
    if (hp <= 12) {
      // Shrimp and bread are in the starter inventory
      await bot.eatFood(/shrimp|bread/i);
    }
  }
  return 'finished';
}

// Run for 30 minutes (30 × 60 × 1000 ms)
(async () => {
  const result = await train(bot, sdk, 30 * 60 * 1000);
  console.log('Training result:', result);
})();
```

**Step 3 – Launch the trainer in the background**  

```bash
bun /tmp/hp_train.ts > /tmp/hp_train.log 2>&1 &
```

The script will keep attacking rats (which yield combat XP and, due to the server’s XP multiplier, also raise hit‑points) and will automatically eat shrimp or bread whenever hit‑points fall to ≤ 12, keeping you alive.

**Step 4 – Monitor progress**  

While the trainer runs, check the real‑game XP rate at any time:

```bash
bun /app/benchmark/shared/check_xp_rate.ts Hitpoints
